/* @autogenerated */
import { CommonModule } from '@angular/common';
import { ChangeDetectorRef, Component, computed, effect, input, output, signal } from '@angular/core';
import {
  CdkDrag,
  CdkDragDrop,
  CdkDropList,
  CdkDropListGroup,
  DragDropModule,
  moveItemInArray,
  transferArrayItem,
} from '@angular/cdk/drag-drop';
import { MatProgressBarModule } from '@angular/material/progress-bar';
import { MatIconModule } from '@angular/material/icon';
import { MatChipsModule } from '@angular/material/chips';
import { DisplayProvider } from '@shared/data/display-provider';
import { SelectionModel } from '@shared/data/selection-model';

export interface KanbanItemMapper<T> {
  column(item: T): string;
  title(item: T): string;
  subtitle?(item: T): string;
  color?(item: T): string;
  badge?(item: T): string | number;
}

export interface KanbanColumn {
  id: string;
  label: string;
  color?: string;
  limit?: number;
}

interface KanbanColumnState {
  col: KanbanColumn;
  items: any[];
}

@Component({
  selector: 'kanban-view',
  standalone: true,
  imports: [CommonModule, DragDropModule, MatProgressBarModule, MatIconModule, MatChipsModule],
  templateUrl: './kanban-view.component.html',
  styleUrls: ['./kanban-view.component.scss'],
})
export class KanbanViewComponent {
  data = input.required<any[] | undefined>();
  mapper = input.required<KanbanItemMapper<any>>();
  columns = input.required<KanbanColumn[]>();
  display = input<DisplayProvider<any>>();
  searching = input<boolean>();
  selectionModel = input<SelectionModel<any> | undefined>();

  next = output<void>();
  activate = output<any>();
  moved = output<{ item: any; from: string; to: string }>();

  columnItems: KanbanColumnState[] = [];

  columnIds = computed(() => this.columns().map((c) => c.id));

  constructor(private cdr: ChangeDetectorRef) {
    effect(() => {
      const items = this.data() ?? [];
      const cols = this.columns();
      const m = this.mapper();
      this.columnItems = cols.map((col) => ({
        col,
        items: items.filter((item) => m.column(item) === col.id),
      }));
    });
  }

  onDrop(event: CdkDragDrop<any[]>, toColId: string): void {
    if (event.previousContainer === event.container) {
      moveItemInArray(event.container.data, event.previousIndex, event.currentIndex);
    } else {
      const item = event.previousContainer.data[event.previousIndex];
      const fromColId = event.previousContainer.id;
      transferArrayItem(event.previousContainer.data, event.container.data, event.previousIndex, event.currentIndex);
      this.moved.emit({ item, from: fromColId, to: toColId });
    }
    this.columnItems = [...this.columnItems];
    this.cdr.markForCheck();
  }

  isOverLimit(col: KanbanColumnState): boolean {
    return !!col.col.limit && col.items.length > col.col.limit;
  }

  isSelected(item: any): boolean {
    return this.selectionModel()?.isSelected(item) ?? false;
  }

  toggleSelect(item: any, event: MouseEvent): void {
    event.stopPropagation();
    this.selectionModel()?.toogle(item);
  }

  label(item: any): string {
    return this.display()?.display(item) ?? this.mapper().title(item);
  }
}
